const STATISTICS_PERCENT_CSV = "# privacy=percent-only; absolute_amounts=false; position_sizes=false; account_identifiers=false; fixture=true; preview=static\r\nscope,period,metric,percent,evidence,method\r\nall_portfolios,selected,gross_return_percent,0.1588,derived,kovrocity-invest-analytics-v2\r\nall_portfolios,selected,net_return_percent,0.1570,derived,kovrocity-invest-analytics-v2\r\nall_portfolios,selected,win_rate_percent,50.0000,derived,closed FIFO cycles only\r\nall_portfolios,selected,max_drawdown_percent,5.9939,derived,persisted snapshots only\r\nportfolio_1,selected,net_return_percent,0.1570,derived,Результат после комиссий относительно начальной стоимости портфеля; пополнения и выводы исключены из дохода.\r\nportfolio_1,selected,win_rate_percent,50.0000,derived,closed FIFO cycles only\r\nportfolio_1,selected,max_drawdown_percent,5.9939,derived,persisted snapshots only\r\nmonthly_best_asset,2026-08,asset_return_percent,3.3066,fixture,SBER\r\nmonthly_worst_asset,2026-08,asset_return_percent,-2.6738,fixture,YNDX\r\n";
const ALLOWED_INSTRUMENTS = new Set(Object.keys(REPORTS));

function clone(value) {
  return JSON.parse(JSON.stringify(value));
}

function requestBody(options) {
  if (!options?.body) return {};
  if (typeof options.body !== 'string' || options.body.length > 16_384) {
    throw new Error('Preview request is invalid.');
  }
  try { return JSON.parse(options.body); } catch { throw new Error('Preview request is invalid.'); }
}

let bootstrap = clone(BASE_BOOTSTRAP);
let syncCount = 0;
let selectedPeriod = 'all';

async function request(path, options = {}) {
  const method = String(options.method || 'GET').toUpperCase();
  const url = new URL(path, 'https://static-fixture.invalid');
  if (url.pathname === '/api/bootstrap' && method === 'GET') {
    const period = url.searchParams.get('period') || 'all';
    if (period === 'custom') throw new Error('В статическом демо доступны готовые периоды. Произвольные даты работают в установленном Workspace.');
    if (!Object.hasOwn(PERIOD_BOOTSTRAPS, period)) throw new Error('Выберите доступный период демо.');
    selectedPeriod = period;
    return { ...clone(PERIOD_BOOTSTRAPS[period]), syncRuns: clone(bootstrap.syncRuns) };
  }
  if (url.pathname === '/api/ai/company-status' && method === 'GET') return clone(bootstrap.aiAvailability);
  if (url.pathname === '/api/ai/company-facts' && method === 'GET') {
    const instrumentUid = url.searchParams.get('instrumentUid');
    if (!ALLOWED_INSTRUMENTS.has(instrumentUid)) throw new Error('Выберите доступный инструмент.');
    return clone(REPORTS[instrumentUid]);
  }
  if (path === '/api/sync' && method === 'POST') {
    syncCount += 1;
    const startedAt = new Date(Date.parse('2026-08-12T10:00:00.000Z') + syncCount * 1000).toISOString();
    bootstrap.syncRuns = [{
      startedAt,
      status: 'completed',
      statusLabel: 'Симулировано в preview',
      rawCount: bootstrap.operations.length,
      normalizedCount: bootstrap.operations.length,
      durationMs: 0,
      completedStages: ['connection', 'raw', 'normalize', 'reconcile', 'analytics'],
    }, ...bootstrap.syncRuns].slice(0, 12);
    return { runId: `preview-sync-${syncCount}`, status: 'completed', normalizedCount: bootstrap.operations.length };
  }
  if (path === '/api/ai/fact-pack' && method === 'POST') {
    const body = requestBody(options);
    if (!ALLOWED_INSTRUMENTS.has(body.instrumentUid)) throw new Error('Выберите доступный инструмент.');
    return clone(REPORTS[body.instrumentUid]);
  }
  if (path === '/api/connection/capture') {
    throw new Error('Нативное подключение недоступно в статическом fixture-preview. Используйте только подписанный Local Node.');
  }
  if (path === '/api/latency/paint' && method === 'POST') return { accepted: false, simulated: true };
  throw new Error('Маршрут недоступен в статическом fixture-preview.');
}

function downloadOperationsCsv() {
  const blob = new Blob([OPERATIONS_CSV], { type: 'text/csv;charset=utf-8' });
  const url = URL.createObjectURL(blob);
  const link = document.createElement('a');
  link.href = url;
  link.download = 'kovrocity-invest-fixture-operations.csv';
  link.hidden = true;
  document.body.append(link);
  link.click();
  link.remove();
  setTimeout(() => URL.revokeObjectURL(url), 0);
}

function downloadStatisticsPercentCsv() {
  const blob = new Blob([PERIOD_STATISTICS_CSV[selectedPeriod] || STATISTICS_PERCENT_CSV], { type: 'text/csv;charset=utf-8' });
  const url = URL.createObjectURL(blob);
  const link = document.createElement('a');
  link.href = url;
  link.download = 'invest-statistics-percent-only.csv';
  link.hidden = true;
  document.body.append(link);
  link.click();
  link.remove();
  setTimeout(() => URL.revokeObjectURL(url), 0);
}

function startMarketStream(onMessage) {
  if (typeof onMessage !== 'function') throw new Error('Preview stream listener is required.');
  let sequence = 0;
  const emit = () => {
    sequence += 1;
    const sourceEventTime = new Date().toISOString();
    const base = 305 + Math.sin(sequence / 5) * 1.8;
    onMessage({
      type: 'market.candle',
      eventId: `preview-candle-${sequence}`,
      sourceEventTime,
      connectorReceivedAt: sourceEventTime,
      simulated: true,
      candle: {
        instrumentUid: 'fixture-share-sber',
        time: sourceEventTime,
        open: base - 0.4,
        high: base + 0.8,
        low: base - 0.9,
        close: base,
        volume: 2300 + sequence * 12,
      },
    });
  };
  const timer = setInterval(emit, 1200);
  return Object.freeze({ close: () => clearInterval(timer), simulated: true });
}

export const runtimeAdapter = Object.freeze({
  kind: "github-pages-static-fixture-preview-v1",
  request,
  downloadOperationsCsv,
  downloadStatisticsPercentCsv,
  startMarketStream,
});
